import{_ as l,a0 as n,w as a,s as Z,ao as i,I as t,a1 as s,A as p,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"樹莓派 Zero 與 Zero W 對比 | LCTT x X-CMD","titleTemplate":false,"description":"樹莓派 Zero 與 Zero W 對比 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"樹莓派 Zero 與 Zero W 對比 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"樹莓派 Zero 與 Zero W 對比 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210915 Raspberry Pi Zero vs Zero W- What-s the Difference","title":"樹莓派 Zero 與 Zero W 對比","tag":"202109","desc":""},"relativePath":"202109/20210915 Raspberry Pi Zero vs Zero W- What-s the Difference.md","filePath":"[post].md"}'),f={name:"202109/20210915 Raspberry Pi Zero vs Zero W- What-s the Difference.md"};function u(m,r,d,b,W,T){const o=n("Link");return a(),Z("div",null,[r[28]||(r[28]=i('<h1 id="樹莓派-zero-與-zero-w-對比" tabindex="-1">樹莓派 Zero 與 Zero W 對比 <a class="header-anchor" href="#樹莓派-zero-與-zero-w-對比" aria-label="Permalink to “樹莓派 Zero 與 Zero W 對比”">​</a></h1><p>樹莓派十年前憑藉 25 美元的迷你電腦掀起了一場革命。隨着時間的推移，樹莓派發布了許多變種。有些是對以前的型號進行升級，有些是為特定目的而製作的。</p><p>在所有的樹莓派模組中，Pi Zero 和 Pi Zero W 是最便宜的型號，旨在用於小規模項目和 IoT 項目。這兩種設備幾乎是相同的，但是它們之間有一些微妙而重要的區別。</p><p><strong>那麼，樹莓派 Zero 和 Zero W 之間的區別是什麼？Zero W 中的 W 代表的是<ruby>無線<rt>Wireless</rt></ruby>，它表示的是 Zero W 模組擁有無線功能。這是這兩個相似模組之間的最大差異。</strong></p><p>讓我們來詳細瞭解一下。</p><h3 id="pi-zero-與-pi-zero-w-之間的主要不同點" tabindex="-1">Pi Zero 與 Pi Zero W 之間的主要不同點 <a class="header-anchor" href="#pi-zero-與-pi-zero-w-之間的主要不同點" aria-label="Permalink to “Pi Zero 與 Pi Zero W 之間的主要不同點”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/raspberry-pi-zero-vs-zero-w.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>樹莓派 Zero 是以在只有 A+ 板一半的大小上提供儘可能多的功能為目標。</p><p>而樹莓派 Zero W 是為了支持無線在後來推出的，在不需要任何附加的組件和模組的情況下就可以使用藍牙和 Wi-Fi。</p><p>這是兩者之間的關鍵區別，其他的規格保持一致。</p><p>所以，如果你需要以下功能：</p><ul><li>802.11 b/g/n 無線網口</li><li>藍牙 4.1</li><li>低功耗藍牙（BLE）</li></ul><p>樹莓派 Zero W 將是你的不二之選。</p><p>此外，樹莓派 Zero W 還提供了一種帶引腳的版本，叫做 “樹莓派 Pi Zero WH”</p><h3 id="樹莓派-zero-和-zero-w-的規格" tabindex="-1">樹莓派 Zero 和 Zero W 的規格 <a class="header-anchor" href="#樹莓派-zero-和-zero-w-的規格" aria-label="Permalink to “樹莓派 Zero 和 Zero W 的規格”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/raspberry-pi-zero-w.png?resize=600%2C400&amp;ssl=1" alt="Raspberry Pi Zero W"></p>',16)),t("p",null,[s(o,{href:"https://itsfoss.com/raspberry-pi-zero-w/"},{default:p(()=>[...r[0]||(r[0]=[e("樹莓派 Zero 和 Zero W 的規格",-1)])]),_:1}),r[1]||(r[1]=e(" 幾乎是一樣的。",-1))]),r[29]||(r[29]=t("p",null,"它們都具有 1 GHz 的單核 CPU 和 512 MB 的 RAM。至於接口方面，一個 mini HDMI 接口，支持 micro USB OTG、micro USB 供電和一個 CSI 攝像頭接口（用於插入一個相機模組）。",-1)),t("p",null,[r[3]||(r[3]=e("這些板子會提供一種叫 ",-1)),s(o,{href:"https://github.com/raspberrypi/hats"},{default:p(()=>[...r[2]||(r[2]=[e("HAT",-1)])]),_:1}),r[4]||(r[4]=e("（",-1)),r[5]||(r[5]=t("ruby",null,[e("頂部附加硬件"),t("rt",null,"Hardware Attached on Top")],-1)),r[6]||(r[6]=e("）兼容的 40 個引腳。但一般情況下，沒有這些可以讓你輕鬆插入接口的引腳。",-1))]),t("p",null,[r[8]||(r[8]=e("你可以根據自己的功能需要選擇使用 ",-1)),s(o,{href:"https://itsfoss.com/raspberry-pi-os/"},{default:p(()=>[...r[7]||(r[7]=[e("各種樹莓派兼容的系統",-1)])]),_:1}),r[9]||(r[9]=e("，但無論哪種情況，我還是推薦你使用樹莓派 OS。",-1))]),r[30]||(r[30]=i('<h3 id="樹莓派-zero-系列值不值得買" tabindex="-1">樹莓派 Zero 系列值不值得買？ <a class="header-anchor" href="#樹莓派-zero-系列值不值得買" aria-label="Permalink to “樹莓派 Zero 系列值不值得買？”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/raspberry-pi-zero-1.png?resize=600%2C400&amp;ssl=1" alt="Raspberry Pi Zero"></p><p>樹莓派 Zero 是一種很受人們喜歡的單片機形式，即使你有很多樹莓派 Zero 的替代品，樹莓派 Zero 仍然是最推薦的選擇。</p><p>當然，除非你有特殊需求。</p><p>除了板子的尺寸之外，定價、功率要求、運算能力也是這款 20 美元以下的板子的主要亮點。</p><p>因此，如果你正在尋找預算內滿足基本功能的單片機，樹莓派 Zero 就是專門為你打造的。</p><h3 id="樹莓派-zero-系列價格怎麼樣" tabindex="-1">樹莓派 Zero 系列價格怎麼樣？ <a class="header-anchor" href="#樹莓派-zero-系列價格怎麼樣" aria-label="Permalink to “樹莓派 Zero 系列價格怎麼樣？”">​</a></h3><p>樹莓派 Zero 售價 <strong>5 美元</strong> ，Zero W 售價 <strong>10 美元左右</strong>，當然，根據其供應情況和地區，定價規則會不一樣，如果你選擇帶引腳的版本樹莓派 Zero WH ，售價大概是 <strong>14 美元</strong> 左右。</p>',8)),t("p",null,[r[11]||(r[11]=e("還有 ",-1)),s(o,{href:"https://itsfoss.com/raspberry-pi-zero-alternatives/"},{default:p(()=>[...r[10]||(r[10]=[e("其他的設備可以代替樹莓派 Zero",-1)])]),_:1}),r[12]||(r[12]=e("，它們價格也相差不大。",-1))]),r[31]||(r[31]=t("hr",null,null,-1)),t("p",null,[r[14]||(r[14]=e("via: ",-1)),s(o,{href:"https://itsfoss.com/raspberry-pi-zero-vs-zero-w/"},{default:p(()=>[...r[13]||(r[13]=[e("https://itsfoss.com/raspberry-pi-zero-vs-zero-w/",-1)])]),_:1})]),t("p",null,[r[19]||(r[19]=e("作者：",-1)),s(o,{href:"https://itsfoss.com/author/ankush/"},{default:p(()=>[...r[15]||(r[15]=[e("Ankush Das",-1)])]),_:1}),r[20]||(r[20]=e(" 選題：",-1)),s(o,{href:"https://github.com/lujun9972"},{default:p(()=>[...r[16]||(r[16]=[e("lujun9972",-1)])]),_:1}),r[21]||(r[21]=e(" 譯者：",-1)),s(o,{href:"https://github.com/anine09"},{default:p(()=>[...r[17]||(r[17]=[e("anine09",-1)])]),_:1}),r[22]||(r[22]=e(" 校對：",-1)),s(o,{href:"https://github.com/wxy"},{default:p(()=>[...r[18]||(r[18]=[e("wxy",-1)])]),_:1})]),t("p",null,[r[25]||(r[25]=e("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...r[23]||(r[23]=[e("LCTT",-1)])]),_:1}),r[26]||(r[26]=e(" 原創編譯，",-1)),s(o,{href:"https://linux.cn/"},{default:p(()=>[...r[24]||(r[24]=[e("Linux中國",-1)])]),_:1}),r[27]||(r[27]=e(" 榮譽推出",-1))])])}const C=l(f,[["render",u]]);export{g as __pageData,C as default};
